# -*- coding: utf-8 -*-
# (speaker, spanish, korean); speaker None => stage direction, "#" => scene heading (neither is a turn)
L, A, K, E, D_ = "Lucas", "Amparo", "Kevin", "Denise", "Daniel"
D = [
("#", "Escena 1 · 8:40 · Sede central de BuildMart, Atlanta", "장면 1 · 오전 8시 40분 · 애틀랜타, BuildMart 본사"),
(None, "Jueves 6 de agosto. Un campus de edificios de cristal a las afueras de Atlanta. En el vestíbulo, una pantalla enorme repite el lema de la empresa. En la recepción les dan una tarjeta que dice «VENDOR» en letras rojas. Pasan por un control de seguridad, como en un aeropuerto.", "8월 6일 목요일. 애틀랜타 외곽의 유리 건물 단지. 로비의 거대한 화면에서 회사 구호가 반복된다. 접수처에서 빨간 글씨로 'VENDOR(공급업체)'라고 적힌 출입증을 받는다. 공항처럼 보안 검색대를 통과한다."),
(K, "¡Lucas! ¡Amparo! Kevin Morales, category manager de pisos y revestimientos. Bienvenidos a BuildMart. Tengo cuarenta y cinco minutos, así que vamos al grano, ¿okay?", "루카스! 암파로! 케빈 모랄레스, 바닥재·벽재 카테고리 매니저예요. BuildMart에 오신 걸 환영해요. 45분 있으니까 바로 본론 갈게요, 오케이?"),
(L, "Buenos días, Kevin. Gracias por recibirnos con tan poco tiempo de aviso.", "안녕하세요, 케빈. 이렇게 급하게 시간 내 주셔서 감사합니다."),
(K, "No, gracias a Daniel. Daniel me enseñó las fotos del lobby de Monterrey y me dije: este producto tiene potencial. Siéntense, siéntense.", "아니요, 다니엘 덕이죠. 다니엘이 몬테레이 로비 사진 보여 줬을 때 생각했어요. 이 제품 잠재력 있다. 앉으세요, 앉으세요."),
(A, "Su español tiene un acento que no conozco. ¿De dónde es usted?", "스페인어 억양이 처음 듣는 억양이네요. 어디 출신이세요?"),
(K, "Del Bronx, de padres boricuas. Puertorriqueño de Nueva York. Y nada de usted, por favor, que me siento como mi abuelo.", "브롱크스요, 부모님이 보리쿠아. 뉴욕의 푸에르토리코 사람이에요. 그리고 존댓말은 제발 빼요. 할아버지가 된 기분이에요."),
(L, "Hecho. De tú, entonces.", "알겠어요. 그럼 말 놓을게요."),
(None, "Una sala pequeña sin ventanas. En la pared, una pantalla con gráficos de ventas. Kevin habla rápido, mezclando español de Nueva York con palabras en inglés.", "창문 없는 작은 회의실. 벽 화면에 매출 그래프. 케빈은 뉴욕식 스페인어에 영어 단어를 섞어 빠르게 말한다."),
(K, "Les explico rápido. Tenemos dos mil cien tiendas. En pisos cerámicos vendemos unos cuarenta millones de pies cuadrados al año. Ahora mismo tenemos un gap en el segmento premium de mármol.", "빨리 설명할게요. 매장이 2,100개예요. 세라믹 바닥재로 1년에 4천만 평방피트쯤 팔아요. 지금 프리미엄 대리석 부문에 공백이 있어요."),
(A, "¿Un gap? ¿Un hueco en la oferta?", "갭이요? 상품 구성에 빈자리가 있다는 거죠?"),
(K, "Eso. El proveedor que teníamos no cumplió el fill rate y lo sacamos. Necesito un mármol blanco en tres SKUs para el planograma de primavera.", "그거요. 기존 공급업체가 필 레이트를 못 맞춰서 뺐어요. 봄 플래노그램에 흰 대리석을 SKU 세 개로 넣어야 해요."),
(L, "Perdona, Kevin. ¿El fill rate es el porcentaje de pedidos servidos completos?", "죄송해요, 케빈. 필 레이트가 주문을 빠짐없이 채워 준 비율인가요?"),
(K, "Exacto. Si yo te pido cien palés y tú me mandas noventa y cinco, tu fill rate es noventa y cinco. Aquí exigimos noventa y ocho. Por debajo, hay chargebacks.", "정확해요. 내가 팔레트 백 개 주문했는데 아흔다섯 개 보내면 필 레이트가 95예요. 여기선 98을 요구해요. 그 밑이면 차지백이 있어요."),
(A, "Chargebacks... Multas, ¿no?", "차지백… 벌금이죠?"),
(K, "Penalizaciones. Te las descontamos de la factura. Entrega tarde, tres por ciento. Etiqueta incorrecta, doscientos cincuenta dólares por palé. Palé mal armado, otro tanto. Está todo en el vendor manual.", "페널티요. 송장에서 빼요. 납품 지연 3%. 라벨 오류 팔레트당 250달러. 팔레트 적재 불량도 똑같이. 전부 공급업체 매뉴얼에 있어요."),
(L, "¿Y cuántas páginas tiene ese manual?", "그 매뉴얼은 몇 쪽이에요?"),
(K, "(sonríe) Doscientas doce. En inglés. Pero tranquilos, lo tenemos también en español, porque la mitad de nuestros proveedores son mexicanos.", "(웃으며) 212쪽. 영어로요. 근데 걱정 마요. 스페인어판도 있어요. 공급업체 절반이 멕시코 회사거든요."),
(L, "¿Y el planograma? ¿Dónde iría el producto en la tienda?", "플래노그램은요? 매장 어디에 제품이 들어가요?"),
(K, "Pasillo doce, pisos. Un módulo de cuatro pies, a la altura de los ojos. Esa es la zona caliente. Ahí el cliente ve la pieza, la toca y se lleva la caja al carrito.", "12번 통로, 바닥재. 4피트짜리 진열대 하나, 눈높이에. 거기가 핫 존이에요. 거기서 고객이 조각을 보고 만져 보고 상자를 카트에 담아요."),
(A, "¿El cliente se lleva las cajas él mismo? ¿No las instala un profesional?", "고객이 상자를 직접 가져가요? 전문가가 시공하지 않고요?"),
(K, "La mitad son contratistas, la otra mitad gente que lo hace los sábados con un video de YouTube. Por eso la caja no puede pesar mucho y la etiqueta tiene que explicarlo todo.", "절반은 시공업자, 절반은 토요일에 유튜브 영상 보면서 직접 하는 사람들이에요. 그래서 상자가 너무 무거우면 안 되고 라벨이 모든 걸 설명해야 해요."),
(L, "Entonces, para ustedes, la caja es casi tan importante como la baldosa.", "그럼 여기선 상자가 타일만큼 중요하네요."),
(K, "Más. La baldosa no habla; la caja, sí. Si la caja no vende, la baldosa se queda en el estante.", "더 중요해요. 타일은 말을 못 하는데 상자는 말을 하잖아요. 상자가 못 팔면 타일은 선반에 남아요."),
(A, "¿Y el volumen? Para esos tres SKUs, ¿de cuánto estamos hablando?", "물량은요? 그 SKU 세 개면 어느 정도 얘기하는 거예요?"),
(K, "Para empezar, dos millones y medio de pies cuadrados al año. Si vende bien, el doble.", "시작은 연 250만 평방피트. 잘 팔리면 두 배."),
(None, "Lucas apunta la cifra. Hace la cuenta debajo, en pequeño: unos doscientos treinta mil metros cuadrados. Más de lo que produce el horno tres en un año entero.", "루카스가 숫자를 적는다. 그 밑에 작게 계산한다. 약 23만 제곱미터. 3호기가 1년 내내 만드는 양보다 많다."),
(A, "¿En cuánto tiempo necesitarían el primer pedido?", "첫 주문은 언제까지 필요해요?"),
(K, "El reset de primavera es en febrero. Necesito el producto en mis centros de distribución el quince de enero. Ni un día más tarde.", "봄 진열 교체가 2월이에요. 1월 15일까지 우리 물류센터에 제품이 들어와야 해요. 하루도 늦으면 안 되고요."),
(L, "¿El reset?", "리셋이요?"),
(K, "El cambio de planograma. Dos veces al año cambiamos todo el pasillo. Si llegas tarde al reset, esperas seis meses.", "플래노그램 교체요. 1년에 두 번 통로 전체를 바꿔요. 리셋에 늦으면 6개월 기다려야 해요."),
(L, "Es un volumen muy importante, Kevin. Más del doble de lo que vendemos hoy en México.", "아주 큰 물량이네요, 케빈. 지금 멕시코에서 파는 것의 두 배가 넘어요."),
(K, "Bienvenidos a América. Aquí todo es grande. Ahora, dos condiciones. La primera: private label.", "아메리카에 오신 걸 환영해요. 여긴 다 커요. 이제 조건 두 개. 첫째, 프라이빗 라벨."),
(A, "¿Marca propia de BuildMart?", "BuildMart 자체 브랜드요?"),
(K, "Correcto. Se va a vender como StoneCraft, nuestra marca de piedra. En la caja, nuestro logo. El de ustedes, en letra chiquita, en el lateral: «Made in Spain».", "맞아요. StoneCraft, 우리 석재 브랜드로 팔 거예요. 상자엔 우리 로고. 당신들 건 옆면에 작은 글씨로. 'Made in Spain'."),
(A, "Entonces el cliente nunca sabrá que es Albalat.", "그럼 고객은 그게 알발라트라는 걸 영영 모르겠네요."),
(K, "El cliente sabrá que es BuildMart. Y que es español, que vende. Créanme, eso hace sentido para los dos.", "고객은 BuildMart라는 걸 알겠죠. 그리고 스페인산이라는 것도요. 그게 팔려요. 믿어요, 양쪽 다한테 말이 되는 얘기예요."),
(L, "¿Y la segunda condición?", "두 번째 조건은요?"),
(K, "El precio. Un dólar con quince el pie cuadrado. DDP, en nuestros tres centros de distribución. Pago a noventa días.", "가격. 평방피트당 1달러 15센트. DDP, 우리 물류센터 세 곳 도착. 결제는 90일."),
(None, "Silencio. Amparo no se mueve. Lucas vuelve a sacar el móvil.", "침묵. 암파로는 꼼짝도 하지 않는다. 루카스가 다시 휴대폰을 꺼낸다."),
(L, "(despacio) Uno quince por diez coma setenta y seis... Doce dólares con treinta y siete el metro. Unos once euros con veinticinco. Puesto en sus almacenes, con aranceles.", "(천천히) 1.15 곱하기 10.76… 미터당 12달러 37센트. 11유로 25센트쯤. 관세 포함해서 창고 도착 기준으로."),
(A, "Quitando el barco, el camión y la aduana, nos quedarían unos siete euros y medio en fábrica.", "배, 트럭, 통관을 빼면 공장 출고 기준으로 7유로 50센트쯤 남겠네요."),
(L, "Kevin, con todo el respeto: eso está por debajo de lo que nos cuesta fabricarlo.", "케빈, 실례지만 그건 저희 생산원가보다 낮아요."),
(K, "Todos dicen eso el primer día. Con este volumen, sus costos bajan. Economías de escala. Llenan los hornos, bajan los costos. Así funciona.", "다들 첫날엔 그렇게 말해요. 이 물량이면 원가가 내려가요. 규모의 경제. 가마를 채우면 원가가 내려가죠. 그게 원리예요."),
(A, "El gas no baja porque vendamos más, Kevin. El gas es el gas.", "물건을 더 판다고 가스값이 내려가진 않아요, 케빈. 가스는 가스예요."),
(K, "(levanta las manos) Okay, okay. Yo no soy ingeniero. Yo vendo pisos. Mi trabajo es conseguir el mejor precio para dos mil cien tiendas.", "(두 손을 들며) 오케이, 오케이. 난 엔지니어가 아니에요. 바닥재 파는 사람이죠. 내 일은 매장 2,100곳을 위해 최고 가격을 받아 내는 거예요."),
(L, "Y el nuestro es seguir existiendo dentro de cinco años. Convendría que buscáramos una fórmula en la que los dos podamos ganar.", "그리고 저희 일은 5년 뒤에도 살아남는 거고요. 둘 다 이길 수 있는 방식을 찾는 게 좋을 것 같아요."),
(K, "¿Una fórmula? ¿Qué tienes en mente?", "방식이요? 뭘 생각하고 있는데요?"),
(L, "Todavía nada cerrado. Quizá menos SKUs, quizá menos tiendas para empezar, quizá un precio distinto para la primera temporada. Hace falta hacer números en Onda.", "아직 정해진 건 없어요. SKU를 줄이거나, 처음엔 매장을 줄이거나, 첫 시즌엔 다른 가격으로 하거나. 온다에서 숫자를 돌려 봐야 해요."),
(K, "Okay. Números. Me encantan los números. Pero no me mandes un PowerPoint de cuarenta páginas. Una página. Con el precio arriba.", "오케이. 숫자. 숫자 좋아요. 근데 40쪽짜리 파워포인트 보내지 마요. 한 장. 가격은 맨 위에."),
(A, "Una página con el precio arriba. Lo tendremos en cuenta.", "가격을 맨 위에 둔 한 장. 참고할게요."),
(K, "Me gusta esa actitud. Mándame una contraoferta. Pero antes, Denise tiene que verlos. Calidad. Sin el okay de Denise, no hay nada que hablar.", "그 태도 좋네요. 역제안 보내요. 근데 그 전에 드니스가 봐야 해요. 품질 담당. 드니스가 오케이 안 하면 얘기할 게 없어요."),
(A, "Perfecto. Calidad es lo que mejor sabemos hacer.", "좋아요. 품질은 저희가 제일 잘하는 거예요."),
(K, "(mira el reloj) Cuarenta y cuatro minutos. Les dije: aquí somos rápidos. Denise los espera en el piso tres.", "(시계를 보며) 44분. 말했죠, 여긴 빨라요. 드니스가 3층에서 기다려요."),

("#", "Escena 2 · 10:30 · Laboratorio de calidad de BuildMart, tercer piso", "장면 2 · 오전 10시 30분 · BuildMart 품질 실험실, 3층"),
(None, "Una sala con mesas de acero, una máquina para dejar caer cajas desde un metro de altura y estanterías llenas de muestras de todos los proveedores. Una mujer de unos cincuenta años, con gafas y bata blanca, los recibe sin sonreír.", "철제 테이블, 상자를 1미터 높이에서 떨어뜨리는 기계, 모든 공급업체의 샘플로 가득한 선반이 있는 방. 안경에 흰 가운을 입은 쉰 살쯤 된 여성이 웃지 않고 맞는다."),
(E, "Denise Carrasco, calidad de proveedores. Siéntense. Tengo una lista.", "드니스 카라스코, 공급업체 품질 담당이에요. 앉으세요. 목록이 있어요."),
(A, "Nosotros también. Adelante.", "저희도 있어요. 시작하세요."),
(E, "Uno: informes de laboratorio americanos. ANSI A137.1 y coeficiente de fricción dinámica en mojado. Mínimo cero coma cuarenta y dos para interiores.", "첫째, 미국 시험 성적서. ANSI A137.1, 그리고 젖은 상태 동마찰계수. 실내는 최소 0.42."),
(A, "El acabado mate y el antideslizante pasaron en Miami la semana pasada. El pulido no lo ofrecemos para suelos húmedos, solo para paredes.", "무광과 미끄럼 방지 마감은 지난주 마이애미에서 통과했어요. 광택은 젖는 바닥용으로는 안 내놓고, 벽용으로만 해요."),
(E, "(levanta la vista por primera vez) ¿No lo ofrecen? Casi todos los proveedores me intentan vender el pulido para baños.", "(처음으로 고개를 들며) 안 내놓는다고요? 공급업체 거의 다 광택을 욕실용으로 팔려고 하는데요."),
(A, "Y casi todos acaban con una demanda. Preferimos perder una venta que ganar un juicio.", "그리고 거의 다 소송으로 끝나죠. 저흰 소송에서 이기느니 판매 하나를 놓치는 게 나아요."),
(E, "¿Tienen el informe por escrito?", "서면 성적서 있어요?"),
(A, "Aquí lo tiene. Laboratorio de Miami, firmado por la doctora Ochoa.", "여기 있어요. 마이애미 시험소, 오초아 박사 서명이에요."),
(E, "(lo hojea) Conozco a Patricia. Si lo firma ella, me vale. Siguiente.", "(훑어보며) 파트리시아 알아요. 그 사람이 서명했으면 인정할게요. 다음."),
(E, "Dos: prueba de caída. Cada caja tiene que aguantar una caída de tres pies sin romper más del uno por ciento de las piezas.", "둘째, 낙하 시험. 상자마다 3피트 높이에서 떨어뜨려도 조각이 1% 넘게 깨지면 안 돼요."),
(L, "¿Podemos hacerla ahora? Traemos dos cajas en el coche.", "지금 해 볼 수 있을까요? 차에 상자 두 개 있어요."),
(E, "¿Traen cajas de verdad? ¿No solo muestras sueltas?", "진짜 상자를 가져왔어요? 낱개 샘플만이 아니라?"),
(A, "Cajas de producción, con su etiqueta, su lote y su calibre. En dos idiomas.", "생산 상자예요. 라벨, 로트, 칼리브레까지 붙은 거요. 두 언어로."),
(E, "(cierra la carpeta) Vayan por ellas. Llevo once años aquí y es la segunda vez que alguien trae cajas reales a la primera reunión.", "(폴더를 덮으며) 가져와요. 여기서 11년 일했는데 첫 미팅에 진짜 상자를 가져온 사람은 두 번째예요."),
(None, "Veinte minutos después, la máquina suelta la primera caja. Golpe seco. Denise la abre con un cúter y cuenta las piezas una por una.", "20분 뒤, 기계가 첫 상자를 떨어뜨린다. 둔탁한 소리. 드니스가 커터칼로 상자를 열고 조각을 하나하나 센다."),
(E, "Ocho piezas. Ninguna rota. (repite con la segunda) Ocho piezas. Una esquina astillada. Una de dieciséis. Seis por ciento.", "여덟 장. 깨진 거 없음. (두 번째 상자로 반복하며) 여덟 장. 모서리 하나 이 나감. 열여섯 장 중 하나. 6퍼센트."),
(A, "(examina la pieza) Es la esquina del palé, no de la pieza. El cartón no tiene protector de esquinas. En la caja americana habría que añadirlo.", "(조각을 살펴보며) 조각이 아니라 상자 모서리 쪽이에요. 골판지에 모서리 보호대가 없어요. 미국용 상자엔 그걸 추가해야겠네요."),
(E, "Eso es. ¿Ve? Usted encontró el problema antes que yo. Eso me gusta.", "그거예요. 보세요? 나보다 먼저 문제를 찾았잖아요. 그게 마음에 들어요."),
(L, "Lo apuntamos. ¿Y el tercer punto de la lista?", "적어 둘게요. 목록의 세 번째는요?"),
(L, "¿Cuánto tiempo nos daría para cambiar el embalaje?", "포장을 바꾸는 데 시간을 얼마나 주실 수 있어요?"),
(E, "El que necesiten antes del primer pedido. Pero cuando lo cambien, me mandan cajas nuevas y repetimos la prueba. Aquí nada se aprueba de palabra.", "첫 주문 전까지 필요한 만큼요. 다만 바꾸면 새 상자를 보내 줘요. 시험을 다시 하게. 여기선 말로 승인되는 건 없어요."),
(E, "Auditoría de fábrica. Antes de firmar nada, un auditor nuestro visita su planta. Condiciones laborales, seguridad, trazabilidad. Si no pasan la auditoría, no hay contrato, aunque Kevin quiera.", "공장 감사요. 뭐든 서명하기 전에 우리 감사관이 공장을 방문해요. 근로 조건, 안전, 추적성. 감사에 통과 못 하면 케빈이 원해도 계약은 없어요."),
(A, "Cuando quieran. En Onda no tenemos nada que esconder. Bueno, quizá el café de la máquina.", "언제든지요. 온다엔 숨길 게 없어요. 음, 자판기 커피 정도는 숨기고 싶지만요."),
(E, "(casi sonríe) Les mando la lista de documentos. Una última cosa: Kevin les habló de private label, ¿verdad?", "(거의 웃으며) 서류 목록 보내 줄게요. 마지막으로 하나. 케빈이 프라이빗 라벨 얘기했죠?"),
(L, "Sí.", "네."),
(E, "No les voy a decir qué hacer. Pero el proveedor que sacamos en mayo vendía con nuestra marca desde hacía seis años. Un día cambiamos de fábrica y nadie lo notó. Piénsenlo.", "어떻게 하라고는 안 할게요. 근데 우리가 5월에 뺀 공급업체는 6년 동안 우리 브랜드로 팔았어요. 어느 날 공장을 바꿨는데 아무도 몰랐죠. 생각해 봐요."),

("#", "Escena 3 · 13:10 · Estacionamiento de BuildMart, dentro del coche de alquiler", "장면 3 · 오후 1시 10분 · BuildMart 주차장, 렌터카 안"),
(None, "El coche de alquiler arde al sol. Ninguno de los dos arranca el motor. Lucas mira la cifra escrita en su cuaderno: 230.000 m².", "렌터카가 햇볕에 달아올라 있다. 둘 다 시동을 걸지 않는다. 루카스가 수첩에 적힌 숫자를 본다. 23만 ㎡."),
(L, "Doscientos treinta mil metros, Amparo. Con eso, el horno tres no para nunca. Los treinta y dos del ERTE tendrían trabajo para años.", "23만 제곱미터예요, 암파로. 그거면 3호기는 절대 안 멈춰요. ERTE에 있던 서른두 명이 몇 년은 일할 수 있어요."),
(A, "A siete euros y medio en fábrica. Con un coste de nueve cuarenta. Perdemos casi dos euros por cada metro que vendemos.", "공장 출고 7유로 50센트에. 원가가 9유로 40센트인데. 한 제곱미터 팔 때마다 2유로 가까이 잃어요."),
(L, "Es su primer número. Siempre empiezan bajo. Si subimos a ocho cincuenta, nueve...", "그쪽 첫 숫자예요. 늘 낮게 시작하잖아요. 8유로 50, 9유로까지 올리면…"),
(A, "Seguiríamos por debajo del coste. Y muy lejos del mínimo de Ramón. Lucas, eso es comprar trabajo con dinero que no tenemos.", "그래도 원가 밑이에요. 라몬의 하한선과는 한참 멀고요. 루카스, 그건 없는 돈으로 일감을 사는 거예요."),
(L, "Lo sé. Pero piensa en la escala. Tres hornos llenos, la fábrica a pleno rendimiento...", "알아요. 하지만 규모를 생각해 봐요. 가마 세 개가 꽉 차고, 공장이 풀가동하고…"),
(A, "Y nuestro nombre en letra chiquita en el lateral de una caja. ¿Has oído a Denise? Seis años, y un día los cambiaron y nadie lo notó.", "그리고 우리 이름은 상자 옆면에 작은 글씨로. 드니스 말 들었잖아요. 6년이었는데 어느 날 바꿨고 아무도 몰랐대요."),
(L, "Lo he oído.", "들었어요."),
(A, "Mi abuelo no encendió un horno de leña en 1958 para que su nombre no salga en la caja. De ninguna manera.", "우리 할아버지가 1958년에 장작 가마에 불을 붙인 건 상자에 이름도 못 올리려고 그런 게 아니에요. 절대 안 돼요."),
(L, "No digo que aceptemos. Digo que no cerremos la puerta. Sería conveniente hacer una contraoferta con nuestra marca, aunque sea más pequeña.", "받아들이자는 게 아니에요. 문을 닫지 말자는 거예요. 규모가 작더라도 우리 브랜드로 역제안을 하는 게 좋을 것 같아요."),
(A, "(lo mira un momento) Eso sí. Una contraoferta con nuestra marca, sí. A su precio, en absoluto.", "(잠시 그를 바라보며) 그건 맞아요. 우리 브랜드로 역제안, 좋아요. 그쪽 가격으로는, 절대 아니고요."),
(None, "Suena el teléfono de Lucas. Es Daniel. Lucas pone el altavoz.", "루카스의 전화가 울린다. 다니엘이다. 루카스가 스피커를 켠다."),
(D_, "¡Gallegos! ¿Cómo les fue con Kevin? ¿Ya son millonarios?", "갈레고들! 케빈하고 어땠어? 벌써 백만장자 됐어?"),
(L, "Nos ofreció un volumen enorme, Daniel. Con marca de ellos y a un precio por debajo del coste.", "엄청난 물량을 제안했어요, 다니엘. 그쪽 브랜드로, 원가보다 낮은 가격에."),
(D_, "(se ríe) Clásico Kevin. Siempre empieza así. Oye, una idea: ¿y si yo soy el importador? Yo me como la aduana, el inventario y los dolores de cabeza. Ustedes me venden a mí, en Valencia, a su precio.", "(웃으며) 전형적인 케빈이지. 늘 그렇게 시작해. 이봐, 아이디어 하나. 내가 수입자가 되면 어때? 통관, 재고, 골치 아픈 건 내가 다 떠안을게. 당신들은 나한테 발렌시아에서 당신들 가격으로 팔면 돼."),
(L, "¿Tú serías el importador? ¿Y quién pagaría los aranceles si cambian?", "당신이 수입자가 된다고요? 그럼 관세가 바뀌면 누가 내요?"),
(D_, "El importador, gallego. Yo. Por eso cobro mi margen. Nadie trabaja gratis en Miami.", "수입자가 내지, 갈레고. 나. 그래서 내 마진을 받는 거고. 마이애미에선 아무도 공짜로 일 안 해."),
(A, "¿Y usted a BuildMart?", "그리고 당신은 BuildMart에요?"),
(D_, "Yo a BuildMart, con la marca de ustedes, en las tiendas del sureste. Que es mi territorio. Piénsenlo y lo hablamos en Miami.", "난 BuildMart에, 당신들 브랜드로, 남동부 매장에. 거긴 내 구역이니까. 생각해 보고 마이애미에서 얘기하자고."),
(A, "Daniel, ¿con nuestra marca en la caja? ¿No StoneCraft?", "다니엘, 상자에 우리 브랜드로요? StoneCraft 말고요?"),
(D_, "Con Albalat en grande, mija. Yo vendo marcas españolas, no cajas blancas. A Kevin ya lo convenceré yo.", "알발라트를 크게, 아가씨. 난 스페인 브랜드를 팔지, 하얀 상자를 파는 게 아니야. 케빈은 내가 설득할게."),
(L, "Lo pensamos. Gracias, Daniel.", "생각해 볼게요. 고마워요, 다니엘."),
(None, "Apenas cuelga, entra otra llamada. Prefijo 404. Atlanta.", "끊자마자 다른 전화가 들어온다. 지역번호 404. 애틀랜타."),
(K, "Lucas, Kevin otra vez. Mira, hablé con mi jefe. Les doy dos semanas para la contraoferta. Pero les aviso: si no me cuadra, tengo una fábrica en Turquía esperando.", "루카스, 또 케빈이에요. 봐요, 상사랑 얘기했어요. 역제안까지 2주 줄게요. 근데 미리 말하는데, 숫자가 안 맞으면 튀르키예에 기다리는 공장이 있어요."),
(L, "¿Una fábrica en Turquía con mármol blanco rectificado y entrega el quince de enero?", "1월 15일 납품에 연마 가공한 흰 대리석을 만드는 튀르키예 공장이요?"),
(K, "(una pausa) Bueno... con mármol blanco, más o menos. Pero existe. Eso tenlo claro.", "(잠시 멈췄다가) 음… 흰 대리석은 대충이요. 근데 있긴 있어요. 그건 분명히 알아 둬요."),
(L, "Lo tengo claro.", "분명히 알아 둘게요."),
(L, "Dos semanas. Entendido. Nos vendría bien recibir el manual de proveedores en español, para estudiarlo bien.", "2주요. 알겠습니다. 공급업체 매뉴얼을 스페인어판으로 받아 볼 수 있으면 좋겠어요. 잘 검토하게요."),
(K, "Te lo mando hoy. Y oye, sin rencor por lo del precio, ¿okay? Es business.", "오늘 보낼게요. 그리고 가격 얘기는 서운해하지 마요, 오케이? 비즈니스니까."),
(L, "Es business. Hasta pronto, Kevin.", "비즈니스죠. 곧 봬요, 케빈."),
(A, "(cuando cuelga) Una fábrica en Turquía esperando. ¿Te lo crees?", "(그가 끊자) 튀르키예에 기다리는 공장이라. 믿어요?"),
(L, "Me creo que existe. No me creo que esté esperando.", "있다는 건 믿어요. 기다리고 있다는 건 안 믿고요."),
(A, "(arranca por fin el coche) Bueno. Mañana me voy. Tú te quedas con dos semanas, un manual de doscientas páginas y Daniel.", "(드디어 시동을 걸며) 좋아요. 내일 난 가요. 당신한텐 2주, 2백 쪽짜리 매뉴얼, 그리고 다니엘이 남네요."),
(L, "Y con una llamada diaria contigo.", "그리고 매일 당신과의 통화도요."),
(A, "Eso no es una opción. Es una condición.", "그건 선택이 아니에요. 조건이에요."),

("#", "Escena 4 · 6:15 (viernes) · Aeropuerto de Atlanta, control de seguridad", "장면 4 · 오전 6시 15분(금요일) · 애틀랜타 공항, 보안 검색대 앞"),
(None, "Viernes 7 de agosto. El aeropuerto más transitado del mundo ya está lleno a esa hora. Amparo tiene la tarjeta de embarque en la mano: Atlanta–Madrid, y después Valencia. Lucas lleva su maleta de muestras, ahora casi vacía.", "8월 7일 금요일. 세계에서 가장 붐비는 공항은 이 시간에도 벌써 가득하다. 암파로 손에는 탑승권이 들려 있다. 애틀랜타–마드리드, 그다음 발렌시아. 루카스는 이제 거의 빈 샘플 가방을 들고 있다."),
(A, "El lunes sale el barco con las placas del lobby y el miércoles tengo a Sergio en la oficina con la promoción de mayo... de septiembre, perdón. Ya no sé ni en qué mes estoy.", "월요일엔 로비 슬래브 실은 배가 출항하고, 수요일엔 세르히오가 5월 판촉… 아니, 9월 판촉 건으로 사무실에 와요. 이젠 몇 월인지도 모르겠네요."),
(L, "Estás en agosto, en Atlanta, a cuarenta grados. Y Marc empieza el colegio el ocho de septiembre.", "8월이고, 애틀랜타고, 40도예요. 그리고 마르크는 9월 8일에 개학하고요."),
(A, "(sonríe) Te acuerdas.", "(미소 지으며) 기억하네요."),
(L, "Me lo has dicho once veces esta semana.", "이번 주에만 열한 번 말했어요."),
(A, "Lucas. En serio. Lo de Kevin, lo de Daniel, lo de Sandra... Van a apretarte por todos lados cuando yo no esté.", "루카스. 진지하게. 케빈, 다니엘, 산드라… 내가 없으면 사방에서 당신을 조일 거예요."),
(L, "Lo sé.", "알아요."),
(A, "Hagas lo que hagas, consúltalo antes. Con Ramón, con mi padre, conmigo. De lo contrario, volvemos a empezar como en Monterrey, y no tengo ganas.", "뭘 하든 먼저 상의해요. 라몬이든, 아빠든, 나든. 안 그러면 몬테레이 때처럼 처음부터 다시 시작이에요. 그러고 싶지 않아요."),
(L, "Te prometo que no firmaré nada sin hablarlo antes contigo.", "당신과 먼저 얘기하지 않고는 아무것도 서명하지 않겠다고 약속할게요."),
(A, "No firmes nada solo. Ni un contrato, ni un correo que parezca un contrato, ni una servilleta.", "혼자서는 아무것도 서명하지 마요. 계약서도, 계약서처럼 보이는 메일도, 냅킨도."),
(L, "Ni una servilleta. Y si tengo que ir a algún sitio, te aviso antes de comprar el billete.", "냅킨도요. 그리고 어디 가야 하면 표 사기 전에 알릴게요."),
(A, "Eso. (le tiende la mano, como en la azotea de Monterrey) Socio.", "그거예요. (몬테레이 옥상에서처럼 손을 내밀며) 소시오."),
(L, "(se la estrecha) Socia. Saluda a Pepe. Y dile que en Texas hay un tal Lalo que quiere conocerlo.", "(악수하며) 소시아. 페페한테 안부 전해 줘요. 텍사스에 랄로라는 사람이 만나고 싶어 한다고도요."),
(A, "Se lo diré. Y tú, cómprate unas botas de verdad.", "전할게요. 그리고 당신은 제대로 된 부츠 좀 사요."),
(None, "Amparo pasa el control de seguridad y se vuelve una vez para levantar la mano. Lucas se queda mirando la fila hasta que desaparece. Luego abre el correo: un mensaje nuevo de Kevin Morales. Adjunto: «Vendor Manual – Español – 212 págs.».", "암파로가 보안 검색대를 지나 한 번 돌아보며 손을 든다. 루카스는 그녀가 사라질 때까지 줄을 바라본다. 그러고 메일을 연다. 케빈 모랄레스의 새 메시지. 첨부 파일: 'Vendor Manual – Español – 212쪽'."),
(L, "(para sí) Dos semanas. Doscientas doce páginas. Y ninguna servilleta.", "(혼잣말로) 2주. 212쪽. 그리고 냅킨은 하나도 없이."),
]

PRE = [
("text", "장면 미리보기", "대화문을 읽기 전에 줄거리를 확인하고, 아래 질문의 답을 찾으며 읽어 보세요.", [
 "애틀랜타, 대형 체인 BuildMart 본사. 카테고리 매니저 케빈 모랄레스는 45분 안에 모든 것을 말한다. 매장 2,100곳, 연 250만 평방피트, 그리고 두 가지 조건. 프라이빗 라벨과 가격. 품질 담당 드니스는 서류와 낙하 시험으로 두 사람을 시험하고, 마지막에 조용히 경고 하나를 남긴다. 주차장의 렌터카 안에서 루카스는 3호기를 가득 채울 숫자에 흔들리고, 암파로는 흔들리지 않는다. 다음 날 새벽, 공항 보안 검색대 앞.",
 "듣기 질문 ① 케빈이 말한 '차지백'의 예 세 가지는? 그가 제시한 가격은 ㎡당 유로로 얼마이며, 왜 받아들일 수 없는가?",
 "듣기 질문 ② 낙하 시험에서 무엇이 깨졌고, 암파로가 찾아낸 원인과 해결책은?",
 "듣기 질문 ③ 다니엘이 전화로 제안한 구조는 무엇이며, 케빈은 역제안 기한을 얼마나 주는가?",
]),
]

